                    }
                    Keyword::Not => {
                        self.expect(Token::Keyword(Keyword::Null))?;
                        nullable = Some(false);
                    }
                    Keyword::Null => {
                        self.expect(Token::Keyword(Keyword::Null))?;
                        nullable = Some(true);
                    }
                    Keyword::Default => {
                        default = Some(self.parse_expression()?);
                    }
                    Keyword::Unique => unique = true,
                    Keyword::Index => index = true,
                    Keyword::References => {
                        references = Some(self.next_ident()?);
