                } else {
                    None
                };
                from.push(ast::From::Join {
                    left: Box::new(from.pop().unwrap()),
                    right: Box::new(right),
                    r#type: join_type,
                    predicate,
                });
            }
            if !self.next_is(Token::Comma) {
                break;
            }
        }
        Ok(from)
    }

    // Parses a FROM table.
    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;
        let alias = if self.next_if_keyword() == Some(Keyword::As) {
            Some(self.next_ident()?)
        } else {
            None
        };
        Ok(ast::From::Table { name, alias })
    }

    // Parses a FROM JOIN type, if present.
    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Cross => return Ok(Some(ast::JoinType::Cross)),
                Keyword::Inner => return Ok(Some(ast::JoinType::Inner)),
                Keyword::Left => {
                    if self.next_if_keyword() == Some(Keyword::Outer) {
                        return Ok(Some(ast::JoinType::Left));
                    }
                    return Ok(Some(ast::JoinType::Left));
                }
                Keyword::Right => {
                    if self.next_if_keyword() == Some(Keyword::Outer) {
                        return Ok(Some(ast::JoinType::Right));
                    }
                    return Ok(Some(ast::JoinType::Right));
                }
                _ => {}
            }
        }
        Ok(None)
    }

    /// Parses a WHERE clause, if present.
    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Where) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses a GROUP BY clause, if present.
    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Group) {
            return Ok(Vec::new());
        }
        self.expect(Token::Keyword(Keyword::By))?;
        let mut group_by = Vec::new();
        loop {
            group_by.push(self.parse_expression()?);
            if !self.next_is(Token::Comma) {
                break;
            }
        }
        Ok(group_by)
    }

    /// Parses a HAVING clause, if present.
    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Having) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an ORDER BY clause, if present.
    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        if self.next_if_keyword() != Some(Keyword::Order) {
            return Ok(Vec::new());
        }
        self.expect(Token::Keyword(Keyword::By))?;
        let mut order_by = Vec::new();
        loop {
            let expr = self.parse_expression()?;
            let dir = if self.next_if_keyword() == Some(Keyword::Asc) {
                ast::Direction::Ascending
            } else if self.next_if_keyword() == Some(Keyword::Desc) {
                ast::Direction::Descending
            } else {
                ast::Direction::Ascending
            };
            order_by.push((expr, dir));
            if !self.next_is(Token::Comma) {
                break;
            }
        }
        Ok(order_by)
    }

    /// Parses a LIMIT clause, if present.
    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Limit) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an OFFSET clause, if present.
    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Offset) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an expression using the precedence climbing algorithm.
    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(Precedence::MIN)
    }

    /// Parses an expression at the given minimum precedence.
    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        // Parse prefix operator.
        let mut lhs = if let Some(op) = self.parse_prefix_operator_at(min_precedence) {
            let rhs = self.parse_expression_at(op.precedence() + op.associativity())?;
            op.into_expression(rhs)
        } else {
            self.parse_expression_atom()?
        };

        loop {
            // Parse infix operator.
            if let Some(op) = self.parse_infix_operator_at(min_precedence) {
                let rhs = self.parse_expression_at(op.precedence() + op.associativity())?;
                lhs = op.into_expression(lhs, rhs);
            } else {
                break;
            }
        }

        // Parse postfix operator.
        if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
            lhs = op.into_expression(lhs);
        }

        Ok(lhs)
    }

    /// Parses an expression atom.
    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        match self.next()? {
            Token::All => Ok(ast::Expression::All),
            Token::Ident(s) => Ok(ast::Expression::Column(None, s)),
            Token::Keyword(kw) => {
                // Check for function call
                if self.next_is(Token::OpenParen) {
                    let mut args = Vec::new();
                    loop {
                        if self.next_is(Token::CloseParen) {
                            break;
                        }
                        args.push(self.parse_expression()?);
                        if !self.next_is(Token::Comma) {
                            break;
                        }
                    }
                    self.expect(Token::CloseParen)?;
                    Ok(ast::Expression::Function(kw.to_string(), args))
                } else {
                    // Check for literal
                    match kw {
                        Keyword::True => Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
                        Keyword::False => Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
                        Keyword::Null => Ok(ast::Expression::Literal(ast::Literal::Null)),
                        Keyword::Infinity => Ok(ast::Expression::Literal(ast::Literal::String("inf".to_string()))),
                        Keyword::NaN => Ok(ast::Expression::Literal(ast::Literal::String("nan".to_string()))),
                        _ => Err(errinput!("unexpected keyword {}", kw)),
                    }
                }
            }
            Token::Number(s) => {
                if s == "inf" || s == "nan" {
                    Ok(ast::Expression::Literal(ast::Literal::String(s)))
                } else if s.contains('.') || s.contains('e') || s.contains('E') {
                    match s.parse::<f64>() {
                        Ok(v) => Ok(ast::Expression::Literal(ast::Literal::Float(v))),
                        Err(_) => Err(errinput!("invalid float: {}", s)),
                    }
                } else {
                    match s.parse::<i64>() {
                        Ok(v) => Ok(ast::Expression::Literal(ast::Literal::Integer(v))),
                        Err(_) => Err(errinput!("invalid integer: {}", s)),
                    }
                }
            }
            Token::String(s) => Ok(ast::Expression::Literal(ast::Literal::String(s))),
            Token::Minus => {
                let expr = self.parse_expression_at(PrefixOperator::Minus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Negate(Box::new(expr))))
            }
            Token::Plus => {
                let expr = self.parse_expression_at(PrefixOperator::Plus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Identity(Box::new(expr))))
            }
            Token::OpenParen => {
                let expr = self.parse_expression()?;
                self.expect(Token::CloseParen)?;
                Ok(expr)
            }
            t => Err(errinput!("unexpected token {}", t)),
        }
    }

    /// Parses a prefix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
        match self.peek()? {
            Some(Token::Minus) if min_precedence <= PrefixOperator::Minus.precedence() => {
                self.next_is(Token::Minus);
                Some(PrefixOperator::Minus)
            }
            Some(Token::Not) if min_precedence <= PrefixOperator::Not.precedence() => {
                self.next_is(Token::Keyword(Keyword::Not));
                Some(PrefixOperator::Not)
            }
            Some(Token::Plus) if min_precedence <= PrefixOperator::Plus.precedence() => {
                self.next_is(Token::Plus);
                Some(PrefixOperator::Plus)
            }
            _ => None,
        }
    }

    /// Parses an infix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        match self.peek()? {
            Some(Token::Keyword(kw)) if min_precedence <= InfixOperator::And.precedence() => {
                if kw == Keyword::And {
                    self.next_is(Token::Keyword(Keyword::And));
                    return Some(InfixOperator::And);
                }
            }
            Some(Token::Keyword(kw)) if min_precedence <= InfixOperator::Or.precedence() => {
                if kw == Keyword::Or {
                    self.next_is(Token::Keyword(Keyword::Or));
                    return Some(InfixOperator::Or);
                }
            }
            Some(Token::Equal) if min_precedence <= InfixOperator::Equal.precedence() => {
                self.next_is(Token::Equal);
                return Some(InfixOperator::Equal);
            }
            Some(Token::NotEqual) if min_precedence <= InfixOperator::NotEqual.precedence() => {
                self.next_is(Token::NotEqual);
                return Some(InfixOperator::NotEqual);
            }
            Some(Token::GreaterThan) if min_precedence <= InfixOperator::GreaterThan.precedence() => {
                self.next_is(Token::GreaterThan);
                return Some(InfixOperator::GreaterThan);
            }
            Some(Token::GreaterThanOrEqual) if min_precedence <= InfixOperator::GreaterThanOrEqual.precedence() => {
                self.next_is(Token::GreaterThanOrEqual);
                return Some(InfixOperator::GreaterThanOrEqual);
            }
            Some(Token::LessThan) if min_precedence <= InfixOperator::LessThan.precedence() => {
                self.next_is(Token::LessThan);
                return Some(InfixOperator::LessThan);
            }
            Some(Token::LessThanOrEqual) if min_precedence <= InfixOperator::LessThanOrEqual.precedence() => {
                self.next_is(Token::LessThanOrEqual);
                return Some(InfixOperator::LessThanOrEqual);
            }
            Some(Token::Like) if min_precedence <= InfixOperator::Like.precedence() => {
                self.next_is(Token::Keyword(Keyword::Like));
                return Some(InfixOperator::Like);
            }
            Some(Token::Plus) if min_precedence <= InfixOperator::Add.precedence() => {
                self.next_is(Token::Plus);
                return Some(InfixOperator::Add);
            }
            Some(Token::Minus) if min_precedence <= InfixOperator::Subtract.precedence() => {
                self.next_is(Token::Minus);
                return Some(InfixOperator::Subtract);
            }
            Some(Token::Asterisk) if min_precedence <= InfixOperator::Multiply.precedence() => {
                self.next_is(Token::Asterisk);
                return Some(InfixOperator::Multiply);
            }
            Some(Token::Slash) if min_precedence <= InfixOperator::Divide.precedence() => {
                self.next_is(Token::Slash);
                return Some(InfixOperator::Divide);
            }
            Some(Token::Caret) if min_precedence <= InfixOperator::Exponentiate.precedence() => {
                self.next_is(Token::Caret);
                return Some(InfixOperator::Exponentiate);
            }
            Some(Token::Percent) if min_precedence <= InfixOperator::Remainder.precedence() => {
                self.next_is(Token::Percent);
                return Some(InfixOperator::Remainder);
            }
            _ => None,
        }
    }

    /// Parses a postfix operator, if there is one and its precedence is at
    /// least min_precedence.
    fn parse_postfix_operator_at(
        &mut self,
        min_precedence: Precedence,
    ) -> Result<Option<PostfixOperator>> {
        match self.peek()? {
            Some(Token::Exclamation) if min_precedence <= PostfixOperator::Factorial.precedence() => {
                self.next_is(Token::Exclamation);
                return Ok(Some(PostfixOperator::Factorial));
            }
            Some(Token::Keyword(kw)) if min_precedence <= PostfixOperator::Is.precedence() => {
                if kw == Keyword::Is {
                    self.next_is(Token::Keyword(Keyword::Is));
                    let lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::Nan) {
                        ast::Literal::String("nan".to_string())
                    } else {
                        return Err(errinput!("expected NULL or NAN after IS"));
                    };
                    return Ok(Some(PostfixOperator::Is(lit)));
                }
                if kw == Keyword::Not {
                    self.next_is(Token::Keyword(Keyword::Not));
                    let lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::Nan) {
                        ast::Literal::String("nan".to_string())
                    } else {
                        return Err(errinput!("expected NULL or NAN after IS NOT"));
                    };
                    return Ok(Some(PostfixOperator::IsNot(lit)));
                }
            }
            _ => {}
        }
        Ok(None)
    }
}
